* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
.nt-wrap {
  height: calc(var(--appsmith-ui-height) * 1px);
  width: calc(var(--appsmith-ui-width) * 1px);
  overflow: auto;
  background: var(--dark-1e293b, var(--appsmith-theme-backgroundColor, #1E293A));
  border: 1px solid var(--appsmith-theme-borderColor, #334155);
  border-radius: 6px;
  font-family: system-ui;
}
table.nt { border-collapse: collapse; width: max-content; min-width: 100%; background: var(--dark-1e293b, var(--appsmith-theme-backgroundColor, #1E293A)); }
table.nt th { padding: 10px 14px; font-size: 12px; font-weight: 700; color: var(--dark-f1f5f9, var(--appsmith-theme-textStrongColor, #ffffff)); white-space: nowrap; text-align: left; border-bottom: 2px solid var(--appsmith-theme-borderMidColor, #475569); background: var(--appsmith-theme-hoverStrongColor, #334155); position: sticky; top: 0; }
table.nt td { padding: 8px 14px; font-size: 12px; color: var(--appsmith-theme-textColor, #e2e8f0); border-bottom: 1px solid var(--appsmith-theme-borderColor, #334155); vertical-align: top; }
table.nt td.nowrap { white-space: nowrap; }
table.nt td.chat { white-space: pre-line; min-width: 320px; max-width: 520px; }
table.nt a { color: var(--appsmith-theme-linkSoftColor, #93c5fd); text-decoration: underline; }
.empty { padding: 20px; color: var(--appsmith-theme-textSecondaryColor, #94a3b8); text-align: center; font-family: system-ui; }

